static const font_glyph_t *find_glyph(char ch)
{
    for (size_t i = 0; i < sizeof(s_font_table) / sizeof(s_font_table[0]); i++) {
        if (s_font_table[i].ch == ch) {
            return &s_font_table[i];
        }
    }
    return NULL; /* unsupported character: rendered as blank */
}

void simple_font_draw_string(uint16_t *buf, int buf_w, int buf_h,
                             int x0, int y0, const char *text,
                             int scale, uint16_t color)
{
    if (buf == NULL || text == NULL || scale <= 0) {
        return;
    }
    int pen_x = x0;
    for (const char *p = text; *p != '\0'; p++) {
        char ch = *p;
        if (ch >= 'a' && ch <= 'z') {
            ch = (char)(ch - 'a' + 'A'); /* fold lowercase to uppercase glyphs */
        }
        const font_glyph_t *glyph = find_glyph(ch);
        if (glyph != NULL) {
            for (int row = 0; row < SIMPLE_FONT_GLYPH_HEIGHT; row++) {
                uint8_t bits = glyph->rows[row];
                for (int col = 0; col < SIMPLE_FONT_GLYPH_WIDTH; col++) {
                    if (bits & (1 << (4 - col))) {
                        for (int sy = 0; sy < scale; sy++) {
                            int py = y0 + row * scale + sy;
                            if (py < 0 || py >= buf_h) continue;
                            for (int sx = 0; sx < scale; sx++) {
                                int px = pen_x + col * scale + sx;
                                if (px < 0 || px >= buf_w) continue;
                                buf[py * buf_w + px] = color;
                            }
                        }
                    }
                }
            }
        }
        pen_x += (SIMPLE_FONT_GLYPH_WIDTH + 1) * scale;
    }
}
